from datetime import date
from typing import Dict, Set


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days: int = loan_days
        self.daily_fine: float = daily_fine

        # Inventory of books added to the library
        self.books: Set[str] = set()

        # book_id -> (user, borrow_date)
        self.active_loans: Dict[str, tuple[str, date]] = {}

        # user -> set of book_ids currently borrowed
        self.user_loans: Dict[str, Set[str]] = {}

        # user -> accumulated unpaid fines
        self.fines: Dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book '{book_id}' does not exist in the library.")

        if book_id in self.active_loans:
            raise ValueError(f"Book '{book_id}' is currently borrowed.")

        current_borrowed = self.user_loans.get(user, set())
        # A user with unpaid fines may hold at most one book at a time
        if self.unpaid_fines(user) > 0 and len(current_borrowed) >= 1:
            raise ValueError(
                f"User '{user}' has unpaid fines and cannot borrow more than one book."
            )

        self.active_loans[book_id] = (user, day)
        self.user_loans.setdefault(user, set()).add(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        if book_id not in self.active_loans or self.active_loans[book_id][0] != user:
            raise ValueError(f"Book '{book_id}' is not currently borrowed by user '{user}'.")

        _, borrow_day = self.active_loans.pop(book_id)
        self.user_loans[user].remove(book_id)

        days_kept = (day - borrow_day).days
        delay = max(0, days_kept - self.loan_days)
        fine = delay * self.daily_fine

        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.fines[user] = 0.0
```

